package edu.zsc.ai.domain.model.dto.request.ai;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.List;

/** Rows generated by a query result, exported through the shared file export pipeline. */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class ExportResultFileRequest {
    @NotBlank(message = "format is required")
    private String format;
    @NotEmpty(message = "headers is required and must not be empty")
    private List<String> headers;
    private List<List<Object>> rows;
}
